export function shouldShowTimelineComponents(
  capture: CaptureAvailability,
  hasPoints: boolean
): boolean {
  if (hasPoints) return true;
  if (capture.reason !== null) return false;
  const producers = [
    capture.foreground,
    capture.keyboard,
    capture.pointer,
    capture.contextSwitch,
  ];
  const degraded = producers.some(
    (producer) =>
      producer !== null &&
      (producer.state === "unavailable" ||
        producer.state === "disabled" ||
        producer.state === "error")
  );
  if (degraded) return false;
  if (producers.some((producer) => producer !== null)) return true;
  return capture.inputDensitySupported;
}

